<?phpif(isset($_POST["golog"])){//session_start();if(isset($_POST["usrnm"])){$user=$_POST["usrnm"];}if(isset($_POST["pswrd"])){$pass=$_POST["pswrd"];}if(empty($user) or empty($pass)){$_SESSION["error"]="Empty username or password";echo("<script>location.href='index.php'</script>");return false;}else{require("setgetcon.php");session_start();if(isset($_SESSION["error"])){unset($_SESSION["error"]);}$db=new Database();$con=$db->getConnection();$sql=$con->prepare("select * from employeestb where username=? and password=? and permission='Yes'");$sql->execute([$user,$pass]);$row=$sql->fetch();$count=$sql->rowCount();if($count==1 and $row['post']=='Admin' ){$_SESSION["type"]="Employee";$_SESSION["code"]=$row["emp_id"];echo("<script>location.href='dashboard.php'</script>");exit();}else{$sql=$con->prepare("select * from schoolinfotb where (username=? or code=?) and password=? ");$sql->execute([$user,$user,$pass]);$row=$sql->fetch();$count=$sql->rowCount(); if($count===1)  {$_SESSION["type"]="School";$_SESSION["code"]=$row["code"];echo("<script>location.href='dashboard.php'</script>");exit(); }  else { $sql=$con->prepare("select * from teacherstb where (username=? or email=? or teachercode=?) and password=? ");$sql->execute([$user,$user,$user,$pass]);$row=$sql->fetch();$count=$sql->rowCount(); if($count===1)     {$_SESSION["type"]="Teacher";$_SESSION["code"]=$row["teachercode"];echo("<script>location.href='dashboard.php'</script>");exit();    }else{                        $_SESSION["error"]="Incorrect username or password";echo("<script>history.back();</script>");return false;}}}}}?>